using System.IO.Compression;
using System.Text;

namespace OtzariaWidget.Calendar.Tests.TestSupport;

/// <summary>
/// Second, independently produced ground truth (QA review): generated by NEW Dart scripts (Golden/generator/qa_*.dart) that import
/// Otzaria's own zmanim_helpers.dart / calendar_location.dart (and copies of calendar_day_cell.dart / calendar_times_panel.dart /
/// calendar_date_helpers.dart functions) with kosher_dart 2.0.20 + timezone 2026e - not derived from the first golden set or from the C# code.
/// </summary>
public static class QaGolden
{
    public static string[] Lines(string resource)
    {
        using var s = typeof(QaGolden).Assembly.GetManifestResourceStream(resource)
            ?? throw new InvalidOperationException("missing golden resource " + resource);
        using var gz = new GZipStream(s, CompressionMode.Decompress);
        using var r = new StreamReader(gz, Encoding.UTF8);
        return r.ReadToEnd().Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
    }
}
